<template><div v-if="draft.pending.value||draft.status.value" class="text-sm" role="status"><template v-if="draft.pending.value">{{tr('发现此编辑器的本地草稿。恢复会保留草稿原版本号，服务器有变化时需要合并。','A local draft exists. Its original revision is retained for conflict checking.')}} <button class="btn btn-outline btn-sm" @click="draft.restore">{{tr('恢复本地草稿','Restore local draft')}}</button> <button class="btn btn-outline btn-sm" @click="draft.discard">{{tr('丢弃草稿','Discard draft')}}</button></template><span v-else-if="draft.status.value==='saved'">{{tr('已自动保存在本机；断线或登录过期后可恢复','Autosaved locally; recover after disconnect or session expiry')}}</span><span v-else-if="draft.status.value==='failed'" class="task-error">{{tr('本地存储失败，请复制内容备份','Local storage failed. Copy your changes to keep a backup.')}}</span></div></template>
<script setup>import {useI18n} from '../i18n';const {tr}=useI18n();defineProps({draft:{type:Object,required:true}});</script>
